U(7,('Physical phenomena around us','በዙሪያችን ያሉ ፊዚካዊ ክስተቶች'),[
 D('reflect',('Reflection of light','የብርሃን ነጸብራቅ'),('Angle of incidence = angle of reflection, both measured from the normal (the line at 90° to the mirror).','የመምቻ ማዕዘን = የነጸብራቅ ማዕዘን፤ ሁለቱም ከቋሚው (ከመስታወቱ ጋር 90° ያለው መስመር) ይለካሉ።'),4),
 D('echo',('Sound and echoes','ድምፅና ማስተጋባት'),('Sound needs a medium; in air it travels about 340 m/s. An echo goes there and back.','ድምፅ መተላለፊያ ያስፈልገዋል፤ በአየር በሰከንድ 340 ሜ ገደማ ይጓዛል። ማስተጋባት ሄዶ ይመለሳል።'),4),
 D('ohm',('Simple circuits (V = I × R)','ቀላል ዑደት (V = I × R)'),('A circuit is a complete path for current. Voltage pushes, current flows, resistance opposes: V = I × R.','ዑደት ለፍሰት የተሟላ መንገድ ነው። ቮልቴጅ ይገፋል፣ ፍሰት ይጓዛል፣ መቋቋም ይቃወማል፦ V = I × R።'),5)],
 [sortm(('How does the heat travel?','ሙቀቱ እንዴት ይጓዛል?'),('Conduction: through solids by touch. Convection: currents in liquids and gases. Radiation: rays that need no medium (sunshine).','ኮንዳክሽን፦ በጠጣሮች በመነካካት። ኮንቬክሽን፦ በፈሳሽና በጋዝ ውስጥ በሚፈስ ጅረት። ራዲዬሽን፦ መተላለፊያ የማይፈልጉ ጨረሮች (የፀሐይ ብርሃን)።'),[('Conduction','ኮንዳክሽን'),('Convection','ኮንቬክሽን'),('Radiation','ራዲዬሽን')],
  [(('a metal spoon in hot tea gets hot','በሙቅ ሻይ ውስጥ ያለ የብረት ማንኪያ ይሞቃል'),0),(('a hot pan handle','የሞቀ መጥበሻ እጀታ'),0),(('water circulating in a boiling pot','በሚፈላ ድስት ውስጥ የሚዞር ውኃ'),1),(('warm air rising from a fire','ከእሳት የሚነሳ ሞቃት አየር'),1),(('feeling the Sun on your face','ፀሐይ ፊታችሁን ስትመታ'),2),(('warming hands near a fire (not touching)','ሳትነኩ በእሳት አጠገብ እጅ ማሞቅ'),2)]),
  quiz(('Light, sound and magnets','ብርሃን፣ ድምፅና ማግኔት'),('White light splits into seven colours (dispersion). Noise pollution harms health. Like magnetic poles repel, unlike poles attract.','ነጭ ብርሃን ወደ ሰባት ቀለማት ይከፈላል (ብትነት)። የድምፅ ብክለት ጤናን ይጎዳል። ተመሳሳይ የማግኔት ዋልታዎች ይገፋፋሉ፣ የተለያዩት ይሳሳባሉ።'),[
  q('Splitting white light into colours is called…','ነጭ ብርሃንን ወደ ቀለማት መክፈል…',[('dispersion','ብትነት'),('reflection','ነጸብራቅ'),('absorption','መምጠጥ')]),
  q('Sound cannot travel through…','ድምፅ የማይጓዝበት…',[('a vacuum','ባዶ ቦታ (ቫኪዩም)'),('water','ውኃ'),('iron','ብረት')]),
  q('In a mirror your right hand looks like a left hand. This is…','በመስታወት ቀኝ እጃችሁ ግራ ይመስላል። ይህ…',[('lateral inversion','ጎናዊ ግልብጥ'),('dispersion','ብትነት'),('refraction','ስብረት')]),
  q('Two north poles brought together will…','ሁለት የሰሜን ዋልታዎች ሲቀራረቡ…',[('repel','ይገፋፋሉ'),('attract','ይሳሳባሉ'),('melt','ይቀልጣሉ')]),
  q('Light-coloured clothes keep you cooler because they…','ፈዛዛ ልብሶች የሚያቀዘቅዙት…',[('reflect more heat','ብዙ ሙቀት ስለሚያንጸባርቁ'),('absorb more heat','ብዙ ሙቀት ስለሚመጡ')])])],
 [q('Angle of incidence 40°. Angle of reflection?','የመምቻ ማዕዘን 40°። የነጸብራቅ?',['40°','50°','80°']),q('Heat moves in liquids mainly by…','ሙቀት በፈሳሽ ውስጥ በዋናነት የሚጓዘው በ…',[('convection','ኮንቬክሽን'),('conduction','ኮንዳክሽን'),('radiation','ራዲዬሽን')]),q('V = 12 V, R = 4 Ω. I = ?','V = 12 V፣ R = 4 Ω። I = ?',['3 A','48 A','16 A']),q('A material that does not let heat pass easily is an…','ሙቀትን በቀላሉ የማያሳልፍ…',[('insulator','ኢንሱሌተር'),('conductor','አስተላላፊ')]),q('White light has how many colours?','ነጭ ብርሃን ስንት ቀለማት አሉት?',['7','3','12'])],
 notes(('Light reflects and splits, sound needs a medium, heat moves three ways, current needs a closed circuit, and magnets attract or repel.','ብርሃን ያንጸባርቃል፣ ይከፈላል፤ ድምፅ መተላለፊያ ይፈልጋል፤ ሙቀት በሦስት መንገድ ይጓዛል፤ ፍሰት የተዘጋ ዑደት ይፈልጋል፤ ማግኔቶች ይሳሳባሉ ወይም ይገፋፋሉ።'),
  [('i = r; plane-mirror image is laterally inverted.','i = r፤ የመስታወት ምስል ጎናዊ ግልብጥ ነው።'),('Sound: vibrations, needs a medium, ~340 m/s in air.','ድምፅ፦ ንዝረት፣ መተላለፊያ ይፈልጋል፣ በአየር ~340 ሜ/ሰ።'),('Heat: conduction, convection, radiation.','ሙቀት፦ ኮንዳክሽን፣ ኮንቬክሽን፣ ራዲዬሽን።'),('Circuit V = IR; like poles repel.','ዑደት V = IR፤ ተመሳሳይ ዋልታዎች ይገፋፋሉ።')],
  [('ነጸብራቅ','reflection','ብርሃን ተመልሶ መንጸባረቅ'),('ኢንሱሌተር','insulator','ሙቀት/ኤሌክትሪክ የማያሳልፍ'),('ዑደት','circuit','የተሟላ የፍሰት መንገድ')],('V = I R: Voltage = current × resistance.','V = I R፦ ቮልቴጅ = ፍሰት × መቋቋም።'),
  [(('Echo heard after 3 s. Distance to the wall?','ማስተጋባት ከ3 ሰከንድ በኋላ ተሰማ። ርቀቱ?'),'510 m'),(('Why are cooking pots metal but handles wood or plastic?','ድስቶች ለምን ብረት፣ እጀታዎቻቸው እንጨት ወይም ፕላስቲክ ሆኑ?'),('metal conducts heat, handles insulate','ብረት ሙቀት ያስተላልፋል፣ እጀታዎቹ ይከላከላሉ'))],
  (('Solar water heater from scrap','ከተረፈ ዕቃ የፀሐይ ውኃ ማሞቂያ'),('Use what you know about heat to make free hot water.','ስለ ሙቀት ያወቃችሁትን በመጠቀም ነጻ ሞቅ ያለ ውኃ ሥሩ።'),[('Paint a bottle or tin black (absorbs radiation).','ጠርሙስ ወይም ጣሳ ጥቁር ቀለም ቀቡ (ጨረርን ይመጣል)።'),('Put it in a box lined with foil, under clear plastic.','በፎይል በተሸፈነ ሳጥን ውስጥ፣ በግልጽ ፕላስቲክ ሥር አስቀምጡ።'),('Measure the water temperature every 30 minutes.','የውኃውን ሙቀት በየ30 ደቂቃው ለኩ።'),('Compare with a bottle left in the shade.','በጥላ ከተቀመጠ ጠርሙስ ጋር አወዳድሩ።')])),
 sm(('Energy we see, hear and feel','የምናየው፣ የምንሰማውና የሚሰማን ኃይል'),[('Light','ብርሃን'),('Sound','ድምፅ'),('Heat','ሙቀት'),('Circuits and magnets','ዑደትና ማግኔት')]),
 ('light, sound, heat, simple circuits, magnetism','ብርሃን፣ ድምፅ፣ ሙቀት፣ ቀላል ዑደት፣ ማግኔቲዝም'))
dump('science')
